var E=F.entnahme;
put("fq5",tb([T("Entnahme pro Jahr","Withdrawal a year"),T("30 Jahre bezahlt","30 years paid"),T("Am Ende mind. wie am Start","End at least at start"),T("Median am Ende (Start = 100)","median at end (start = 100)"),T("Schlechtester Fall","worst case")],E.rows.map(function(r){return[P(r.rate),(r.success>=1?"100 %":P(r.success)),P(r.keep),N(r.median,0),(r.worst<=0?T("leer","empty"):N(r.worst,0))]}))+nt(T("<b>Testergebnis:</b> S&amp;P 500 real mit Dividenden ab "+E.since+", Startmonate bis "+E.last_start+", monatliche inflationsbereinigte Entnahme vom Startwert, 30 Jahre. „30 Jahre bezahlt“ heißt: Jede Entnahme konnte gezahlt werden, das Depot war am Ende nicht leer. Das heißt nicht, dass es gleich groß blieb: „Am Ende mind. wie am Start“ zählt nur die Fälle, in denen das Depot am Ende inflationsbereinigt mindestens so groß war wie am Anfang. Als sicher galt ein Anteil von mindestens 95 % bei „30 Jahre bezahlt“: Das erfüllen 3, 3,5 und 4 %. Bei 4 % war das Depot in 98 % der Startmonate nicht leer und in 83 % am Ende mindestens so groß wie am Start; im schlechtesten Fall war es leer. Bei 5 % waren es 83 und 65 %, bei 6 % 70 und 53 %. Einschränkung: nur US-Daten, die Fenster überlappen stark. ","<b>Test result:</b> S&amp;P 500 real with dividends from "+E.since+", start months to "+E.last_start+", monthly inflation-adjusted withdrawal of the starting value, 30 years. “30 years paid” means every withdrawal could be paid, the portfolio was not empty at the end. It does not mean it stayed the same size: “End at least at start” counts only cases where the portfolio ended, inflation-adjusted, at least as large as at the beginning. A share of at least 95 % for “30 years paid” counted as safe: 3, 3.5 and 4 % meet it. At 4 % the portfolio was not empty in 98 % of start months and ended at least at its start value in 83 %; in the worst case it was empty. At 5 % the figures were 83 and 65 %, at 6 % 70 and 53 %. Caveat: US data only, the windows overlap heavily. ")+cap));
